If no vulnerability is detected, you should only output in this json format {"output_list": []}.
Smart contract code:

pragma solidity ^0.8.1; interface IERC20 { function totalSupply() external view returns (uint256); function balanceOf(address account) external view returns (uint256); function transfer(address recipient, uint256 amount) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 amount) external returns (bool); function transferFrom(address sender, address recipient, uint256 amount) external returns (bool); event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); } interface IFYToken is IERC20 { function underlying() external view returns (address); function maturity() external view returns (uint256); function mature() external; function redeem(address to, uint256 amount) external returns (uint256); function mint(address to, uint256 fyTokenAmount) external; function burn(address from, uint256 fyTokenAmount) external; } interface IOracle { function peek(bytes32 base, bytes32 quote, uint256 amount) external view returns (uint256 value, uint256 updateTime); function get(bytes32 base, bytes32 quote, uint256 amount) external returns (uint256 value, uint256 updateTime); } library DataTypes { struct Series { IFYToken fyToken; bytes6 baseId; uint32 maturity; } struct Debt { uint96 max; uint24 min; uint8 dec; uint128 sum; } struct SpotOracle { IOracle oracle; uint32 ratio; } struct Vault { address owner; bytes6 seriesId; bytes6 ilkId; } struct Balances { uint128 art; uint128 ink; } } contract AccessControl { struct RoleData { mapping (address => bool) members; bytes4 adminRole; } mapping (bytes4 => RoleData) private _roles; bytes4 public constant ROOT = 0x00000000; bytes4 public constant LOCK = 0xFFFFFFFF; event RoleAdminChanged(bytes4 indexed role, bytes4 indexed newAdminRole); event RoleGranted(bytes4 indexed role, address indexed account, address indexed sender); event RoleRevoked(bytes4 indexed role, address indexed account, address indexed sender); constructor () { _grantRole(ROOT, msg.sender); _setRoleAdmin(LOCK, LOCK); } modifier auth() { require (_hasRole(msg.sig, msg.sender), "Access denied"); _; } modifier admin(bytes4 role) { require (_hasRole(_getRoleAdmin(role), msg.sender), "Only admin"); _; } function hasRole(bytes4 role, address account) external view returns (bool) { return _hasRole(role, account); } function getRoleAdmin(bytes4 role) external view returns (bytes4) { return _getRoleAdmin(role); } function setRoleAdmin(bytes4 role, bytes4 adminRole) external virtual admin(role) { _setRoleAdmin(role, adminRole); } function grantRole(bytes4 role, address account) external virtual admin(role) { _grantRole(role, account); } function grantRoles(bytes4[] memory roles, address account) external virtual { for (uint256 i = 0; i < roles.length; i++) { require (_hasRole(_getRoleAdmin(roles[i]), msg.sender), "Only admin"); _grantRole(roles[i], account); } } function lockRole(bytes4 role) external virtual admin(role) { _setRoleAdmin(role, LOCK); } function revokeRole(bytes4 role, address account) external virtual admin(role) { _revokeRole(role, account); } function revokeRoles(bytes4[] memory roles, address account) external virtual { for (uint256 i = 0; i < roles.length; i++) { require (_hasRole(_getRoleAdmin(roles[i]), msg.sender), "Only admin"); _revokeRole(roles[i], account); } } function renounceRole(bytes4 role, address account) external virtual { require(account == msg.sender, "Renounce only for self"); _revokeRole(role, account); } function _hasRole(bytes4 role, address account) internal view returns (bool) { return _roles[role].members[account]; } function _getRoleAdmin(bytes4 role) internal view returns (bytes4) { return _roles[role].adminRole; } function _setRoleAdmin(bytes4 role, bytes4 adminRole) internal virtual { if (_getRoleAdmin(role) != adminRole) { _roles[role].adminRole = adminRole; emit RoleAdminChanged(role, adminRole); } } function _grantRole(bytes4 role, address account) internal { if (!_hasRole(role, account)) { _roles[role].members[account] = true; emit RoleGranted(role, account, msg.sender); } } function _revokeRole(bytes4 role, address account) internal { if (_hasRole(role, account)) { _roles[role].members[account] = false; emit RoleRevoked(role, account, msg.sender); } } } library WMul { function wmul(uint256 x, uint256 y) internal pure returns (uint256 z) { z = x * y; unchecked { z /= 1e18; } } } library WDiv { function wdiv(uint256 x, uint256 y) internal pure returns (uint256 z) { z = (x * 1e18) / y; } } library CastU128I128 { function i128(uint128 x) internal pure returns (int128 y) { require (x <= uint128(type(int128).max), "Cast overflow"); y = int128(x); } } library CastI128U128 { function u128(int128 x) internal pure returns (uint128 y) { require (x >= 0, "Cast overflow"); y = uint128(x); } } library CastU256U32 { function u32(uint256 x) internal pure returns (uint32 y) { require (x <= type(uint32).max, "Cast overflow"); y = uint32(x); } } library CastU256I256 { function i256(uint256 x) internal pure returns (int256 y) { require (x <= uint256(type(int256).max), "Cast overflow"); y = int256(x); } } library CauldronMath { function add(uint128 x, int128 y) internal pure returns (uint128 z) { require (y > 0 || x >= uint128(-y), "Result below zero"); z = y > 0 ? x + uint128(y) : x - uint128(-y); } } contract Cauldron is AccessControl() { using CauldronMath for uint128; using WMul for uint256; using WDiv for uint256; using CastU128I128 for uint128; using CastU256U32 for uint256; using CastU256I256 for uint256; using CastI128U128 for int128; event AuctionIntervalSet(uint32 indexed auctionInterval); event AssetAdded(bytes6 indexed assetId, address indexed asset); event SeriesAdded(bytes6 indexed seriesId, bytes6 indexed baseId, address indexed fyToken); event IlkAdded(bytes6 indexed seriesId, bytes6 indexed ilkId); event SpotOracleAdded(bytes6 indexed baseId, bytes6 indexed ilkId, address indexed oracle, uint32 ratio); event RateOracleAdded(bytes6 indexed baseId, address indexed oracle); event DebtLimitsSet(bytes6 indexed baseId, bytes6 indexed ilkId, uint96 max, uint24 min, uint8 dec); event VaultBuilt(bytes12 indexed vaultId, address indexed owner, bytes6 indexed seriesId, bytes6 ilkId); event VaultTweaked(bytes12 indexed vaultId, bytes6 indexed seriesId, bytes6 indexed ilkId); event VaultDestroyed(bytes12 indexed vaultId); event VaultGiven(bytes12 indexed vaultId, address indexed receiver); event VaultPoured(bytes12 indexed vaultId, bytes6 indexed seriesId, bytes6 indexed ilkId, int128 ink, int128 art); event VaultStirred(bytes12 indexed from, bytes12 indexed to, uint128 ink, uint128 art); event VaultRolled(bytes12 indexed vaultId, bytes6 indexed seriesId, uint128 art); event VaultLocked(bytes12 indexed vaultId, uint256 indexed timestamp); event SeriesMatured(bytes6 indexed seriesId, uint256 rateAtMaturity); mapping (bytes6 => address) public assets; mapping (bytes6 => DataTypes.Series) public series; mapping (bytes6 => mapping(bytes6 => bool)) public ilks; mapping (bytes6 => IOracle) public rateOracles; mapping (bytes6 => mapping(bytes6 => DataTypes.SpotOracle)) public spotOracles; mapping (bytes6 => mapping(bytes6 => DataTypes.Debt)) public debt; mapping (bytes6 => uint256) public ratesAtMaturity; uint32 public auctionInterval; mapping (bytes12 => DataTypes.Vault) public vaults; mapping (bytes12 => DataTypes.Balances) public balances; mapping (bytes12 => uint32) public auctions; function addAsset(bytes6 assetId, address asset) external auth { require (assetId != bytes6(0), "Asset id is zero"); require (assets[assetId] == address(0), "Id already used"); assets[assetId] = asset; emit AssetAdded(assetId, address(asset)); } function setDebtLimits(bytes6 baseId, bytes6 ilkId, uint96 max, uint24 min, uint8 dec) external auth { require (assets[baseId] != address(0), "Base not found"); require (assets[ilkId] != address(0), "Ilk not found"); DataTypes.Debt memory debt_ = debt[baseId][ilkId]; debt_.max = max; debt_.min = min; debt_.dec = dec; debt[baseId][ilkId] = debt_; emit DebtLimitsSet(baseId, ilkId, max, min, dec); } function setRateOracle(bytes6 baseId, IOracle oracle) external auth { require (assets[baseId] != address(0), "Base not found"); rateOracles[baseId] = oracle; emit RateOracleAdded(baseId, address(oracle)); } function setAuctionInterval(uint32 auctionInterval_) external auth { auctionInterval = auctionInterval_; emit AuctionIntervalSet(auctionInterval_); } function setSpotOracle(bytes6 baseId, bytes6 ilkId, IOracle oracle, uint32 ratio) external auth { require (assets[baseId] != address(0), "Base not found"); require (assets[ilkId] != address(0), "Ilk not found"); spotOracles[baseId][ilkId] = DataTypes.SpotOracle({ oracle: oracle, ratio: ratio }); emit SpotOracleAdded(baseId, ilkId, address(oracle), ratio); } function addSeries(bytes6 seriesId, bytes6 baseId, IFYToken fyToken) external auth { require (seriesId != bytes6(0), "Series id is zero"); address base = assets[baseId]; require (base != address(0), "Base not found"); require (fyToken != IFYToken(address(0)), "Series need a fyToken"); require (fyToken.underlying() == base, "Mismatched series and base"); require (rateOracles[baseId] != IOracle(address(0)), "Rate oracle not found"); require (series[seriesId].fyToken == IFYToken(address(0)), "Id already used"); series[seriesId] = DataTypes.Series({ fyToken: fyToken, maturity: fyToken.maturity().u32(), baseId: baseId }); emit SeriesAdded(seriesId, baseId, address(fyToken)); } function addIlks(bytes6 seriesId, bytes6[] calldata ilkIds) external auth { DataTypes.Series memory series_ = series[seriesId]; require ( series_.fyToken != IFYToken(address(0)), "Series not found" ); for (uint256 i = 0; i < ilkIds.length; i++) { require ( spotOracles[series_.baseId][ilkIds[i]].oracle != IOracle(address(0)), "Spot oracle not found" ); ilks[seriesId][ilkIds[i]] = true; emit IlkAdded(seriesId, ilkIds[i]); } } function build(address owner, bytes12 vaultId, bytes6 seriesId, bytes6 ilkId) external auth returns(DataTypes.Vault memory vault) { require (vaultId != bytes12(0), "Vault id is zero"); require (vaults[vaultId].seriesId == bytes6(0), "Vault already exists"); require (ilks[seriesId][ilkId] == true, "Ilk not added to series"); vault = DataTypes.Vault({ owner: owner, seriesId: seriesId, ilkId: ilkId }); vaults[vaultId] = vault; emit VaultBuilt(vaultId, owner, seriesId, ilkId); } function destroy(bytes12 vaultId) external auth { DataTypes.Balances memory balances_ = balances[vaultId]; require (balances_.art == 0 && balances_.ink == 0, "Only empty vaults"); delete auctions[vaultId]; delete vaults[vaultId]; emit VaultDestroyed(vaultId); } function _tweak(bytes12 vaultId, DataTypes.Vault memory vault) internal { require (ilks[vault.seriesId][vault.ilkId] == true, "Ilk not added to series"); vaults[vaultId] = vault; emit VaultTweaked(vaultId, vault.seriesId, vault.ilkId); } function tweak(bytes12 vaultId, bytes6 seriesId, bytes6 ilkId) external auth returns(DataTypes.Vault memory vault) { DataTypes.Balances memory balances_ = balances[vaultId]; vault = vaults[vaultId]; if (seriesId != vault.seriesId) { require (balances_.art == 0, "Only with no debt"); vault.seriesId = seriesId; } if (ilkId != vault.ilkId) { require (balances_.ink == 0, "Only with no collateral"); vault.ilkId = ilkId; } _tweak(vaultId, vault); } function _give(bytes12 vaultId, address receiver) internal returns(DataTypes.Vault memory vault) { vault = vaults[vaultId]; vault.owner = receiver; vaults[vaultId] = vault; emit VaultGiven(vaultId, receiver); } function give(bytes12 vaultId, address receiver) external auth returns(DataTypes.Vault memory vault) { vault = _give(vaultId, receiver); } function vaultData(bytes12 vaultId, bool getSeries) internal view returns (DataTypes.Vault memory vault_, DataTypes.Series memory series_, DataTypes.Balances memory balances_) { vault_ = vaults[vaultId]; require (vault_.seriesId != bytes6(0), "Vault not found"); if (getSeries) series_ = series[vault_.seriesId]; balances_ = balances[vaultId]; } function stir(bytes12 from, bytes12 to, uint128 ink, uint128 art) external auth returns (DataTypes.Balances memory, DataTypes.Balances memory) { (DataTypes.Vault memory vaultFrom, , DataTypes.Balances memory balancesFrom) = vaultData(from, false); (DataTypes.Vault memory vaultTo, , DataTypes.Balances memory balancesTo) = vaultData(to, false); if (ink > 0) { require (vaultFrom.ilkId == vaultTo.ilkId, "Different collateral"); balancesFrom.ink -= ink; balancesTo.ink += ink; } if (art > 0) { require (vaultFrom.seriesId == vaultTo.seriesId, "Different series"); balancesFrom.art -= art; balancesTo.art += art; } balances[from] = balancesFrom; balances[to] = balancesTo; if (ink > 0) require(_level(vaultFrom, balancesFrom, series[vaultFrom.seriesId]) >= 0, "Undercollateralized at origin"); if (art > 0) require(_level(vaultTo, balancesTo, series[vaultTo.seriesId]) >= 0, "Undercollateralized at destination"); emit VaultStirred(from, to, ink, art); return (balancesFrom, balancesTo); } function _pour( bytes12 vaultId, DataTypes.Vault memory vault_, DataTypes.Balances memory balances_, DataTypes.Series memory series_, int128 ink, int128 art ) internal returns (DataTypes.Balances memory) { if (ink != 0) { balances_.ink = balances_.ink.add(ink); } if (art != 0) { DataTypes.Debt memory debt_ = debt[series_.baseId][vault_.ilkId]; balances_.art = balances_.art.add(art); debt_.sum = debt_.sum.add(art); uint128 dust = debt_.min * uint128(10) ** debt_.dec; uint128 line = debt_.max * uint128(10) ** debt_.dec; require (balances_.art == 0 || balances_.art >= dust, "Min debt not reached"); if (art > 0) require (debt_.sum <= line, "Max debt exceeded"); debt[series_.baseId][vault_.ilkId] = debt_; } balances[vaultId] = balances_; emit VaultPoured(vaultId, vault_.seriesId, vault_.ilkId, ink, art); return balances_; } function pour(bytes12 vaultId, int128 ink, int128 art) external auth returns (DataTypes.Balances memory) { (DataTypes.Vault memory vault_, DataTypes.Series memory series_, DataTypes.Balances memory balances_) = vaultData(vaultId, true); balances_ = _pour(vaultId, vault_, balances_, series_, ink, art); if (balances_.art > 0 && (ink < 0 || art > 0)) require(_level(vault_, balances_, series_) >= 0, "Undercollateralized"); return balances_; } function grab(bytes12 vaultId, address receiver) external auth { uint32 now_ = uint32(block.timestamp); require (auctions[vaultId] + auctionInterval <= now_, "Vault under auction"); (DataTypes.Vault memory vault_, DataTypes.Series memory series_, DataTypes.Balances memory balances_) = vaultData(vaultId, true); require(_level(vault_, balances_, series_) < 0, "Not undercollateralized"); auctions[vaultId] = now_; _give(vaultId, receiver); emit VaultLocked(vaultId, now_); } function slurp(bytes12 vaultId, uint128 ink, uint128 art) external auth returns (DataTypes.Balances memory) { (DataTypes.Vault memory vault_, DataTypes.Series memory series_, DataTypes.Balances memory balances_) = vaultData(vaultId, true); balances_ = _pour(vaultId, vault_, balances_, series_, -(ink.i128()), -(art.i128())); return balances_; } function roll(bytes12 vaultId, bytes6 newSeriesId, int128 art) external auth returns (DataTypes.Vault memory, DataTypes.Balances memory) { (DataTypes.Vault memory vault_, DataTypes.Series memory oldSeries_, DataTypes.Balances memory balances_) = vaultData(vaultId, true); DataTypes.Series memory newSeries_ = series[newSeriesId]; require (oldSeries_.baseId == newSeries_.baseId, "Mismatched bases in series"); vault_.seriesId = newSeriesId; _tweak(vaultId, vault_); balances_ = _pour(vaultId, vault_, balances_, newSeries_, 0, art); require(_level(vault_, balances_, newSeries_) >= 0, "Undercollateralized"); emit VaultRolled(vaultId, newSeriesId, balances_.art); return (vault_, balances_); } function level(bytes12 vaultId) public returns (int256) { (DataTypes.Vault memory vault_, DataTypes.Series memory series_, DataTypes.Balances memory balances_) = vaultData(vaultId, true); return _level(vault_, balances_, series_); } function mature(bytes6 seriesId) public { DataTypes.Series memory series_ = series[seriesId]; require (uint32(block.timestamp) >= series_.maturity, "Only after maturity"); require (ratesAtMaturity[seriesId] == 0, "Already matured"); _mature(seriesId, series_); } function _mature(bytes6 seriesId, DataTypes.Series memory series_) internal { IOracle rateOracle = rateOracles[series_.baseId]; (uint256 rateAtMaturity,) = rateOracle.get(series_.baseId, bytes32("rate"), 1e18); ratesAtMaturity[seriesId] = rateAtMaturity; emit SeriesMatured(seriesId, rateAtMaturity); } function accrual(bytes6 seriesId) public returns (uint256) { DataTypes.Series memory series_ = series[seriesId]; require (uint32(block.timestamp) >= series_.maturity, "Only after maturity"); return _accrual(seriesId, series_); } function _accrual(bytes6 seriesId, DataTypes.Series memory series_) private returns (uint256 accrual_) { uint256 rateAtMaturity = ratesAtMaturity[seriesId]; if (rateAtMaturity == 0) { _mature(seriesId, series_); } else { IOracle rateOracle = rateOracles[series_.baseId]; (uint256 rate,) = rateOracle.get(series_.baseId, bytes32("rate"), 1e18); accrual_ = rate.wdiv(rateAtMaturity); } accrual_ = accrual_ >= 1e18 ? accrual_ : 1e18; } function _level( DataTypes.Vault memory vault_, DataTypes.Balances memory balances_, DataTypes.Series memory series_ ) internal returns (int256) { DataTypes.SpotOracle memory spotOracle_ = spotOracles[series_.baseId][vault_.ilkId]; uint256 ratio = uint256(spotOracle_.ratio) * 1e12; (uint256 inkValue,) = spotOracle_.oracle.get(series_.baseId, vault_.ilkId, balances_.ink); if (uint32(block.timestamp) >= series_.maturity) { uint256 accrual_ = _accrual(vault_.seriesId, series_); return inkValue.i256() - uint256(balances_.art).wmul(accrual_).wmul(ratio).i256(); } return inkValue.i256() - uint256(balances_.art).wmul(ratio).i256(); } } interface IERC3156FlashBorrower { function onFlashLoan( address initiator, address token, uint256 amount, uint256 fee, bytes calldata data ) external returns (bytes32); } interface IERC3156FlashLender { function maxFlashLoan( address token ) external view returns (uint256); function flashFee( address token, uint256 amount ) external view returns (uint256); function flashLoan( IERC3156FlashBorrower receiver, address token, uint256 amount, bytes calldata data ) external returns (bool); } interface IERC20Metadata is IERC20 { function name() external view returns (string memory); function symbol() external view returns (string memory); function decimals() external view returns (uint8); } contract ERC20 is IERC20Metadata { uint256 internal _totalSupply; mapping (address => uint256) internal _balanceOf; mapping (address => mapping (address => uint256)) internal _allowance; string public override name = "???"; string public override symbol = "???"; uint8 public override decimals = 18; constructor(string memory name_, string memory symbol_, uint8 decimals_) { name = name_; symbol = symbol_; decimals = decimals_; } function totalSupply() external view virtual override returns (uint256) { return _totalSupply; } function balanceOf(address guy) external view virtual override returns (uint256) { return _balanceOf[guy]; } function allowance(address owner, address spender) external view virtual override returns (uint256) { return _allowance[owner][spender]; } function approve(address spender, uint wad) external virtual override returns (bool) { return _setAllowance(msg.sender, spender, wad); } function transfer(address dst, uint wad) external virtual override returns (bool) { return _transfer(msg.sender, dst, wad); } function transferFrom(address src, address dst, uint wad) external virtual override returns (bool) { _decreaseAllowance(src, wad); return _transfer(src, dst, wad); } function _transfer(address src, address dst, uint wad) internal virtual returns (bool) { require(_balanceOf[src] >= wad, "ERC20: Insufficient balance"); unchecked { _balanceOf[src] = _balanceOf[src] - wad; } _balanceOf[dst] = _balanceOf[dst] + wad; emit Transfer(src, dst, wad); return true; } function _setAllowance(address owner, address spender, uint wad) internal virtual returns (bool) { _allowance[owner][spender] = wad; emit Approval(owner, spender, wad); return true; } function _decreaseAllowance(address src, uint wad) internal virtual returns (bool) { if (src != msg.sender) { uint256 allowed = _allowance[src][msg.sender]; if (allowed != type(uint).max) { require(allowed >= wad, "ERC20: Insufficient approval"); unchecked { _setAllowance(src, msg.sender, allowed - wad); } } } return true; } function _mint(address dst, uint wad) internal virtual returns (bool) { _balanceOf[dst] = _balanceOf[dst] + wad; _totalSupply = _totalSupply + wad; emit Transfer(address(0), dst, wad); return true; } function _burn(address src, uint wad) internal virtual returns (bool) { unchecked { require(_balanceOf[src] >= wad, "ERC20: Insufficient balance"); _balanceOf[src] = _balanceOf[src] - wad; _totalSupply = _totalSupply - wad; emit Transfer(src, address(0), wad); } return true; } } interface IERC2612 { function permit(address owner, address spender, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external; function nonces(address owner) external view returns (uint256); } abstract contract ERC20Permit is ERC20, IERC2612 { mapping (address => uint256) public override nonces; bytes32 public immutable PERMIT_TYPEHASH = keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)"); bytes32 private immutable _DOMAIN_SEPARATOR; uint256 public immutable deploymentChainId; constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_, decimals_) { uint256 chainId; assembly {chainId := chainid()} deploymentChainId = chainId; _DOMAIN_SEPARATOR = _calculateDomainSeparator(chainId); } function _calculateDomainSep